describe('Pinch-to-Zoom on Product Images', () => {
    beforeEach(() => {
        cy.visit('/product-page'); // Replace with the actual product page URL
    });

    it('should zoom in on the product image when pinching out', () => {
        cy.get('.product-image') // Replace with the actual selector for the product image
            .trigger('touchstart', { touches: [{ clientX: 100, clientY: 100 }, { clientX: 200, clientY: 100 }] })
            .trigger('touchmove', { touches: [{ clientX: 150, clientY: 100 }, { clientX: 250, clientY: 100 }] })
            .trigger('touchend');

        cy.get('.product-image').should('have.css', 'transform').and('include', 'scale(1.5)'); // Adjust scale value as needed
    });

    it('should not zoom in when pinch gesture is not performed', () => {
        cy.get('.product-image') // Replace with the actual selector for the product image
            .trigger('touchstart', { touches: [{ clientX: 100, clientY: 100 }] })
            .trigger('touchend');

        cy.get('.product-image').should('have.css', 'transform').and('not.include', 'scale'); 
    });
});
